CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.customer_settings (user_id uuid PRIMARY KEY, display_name text NOT NULL DEFAULT '', newsletter boolean NOT NULL DEFAULT false);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.customer_settings TO authenticated; GRANT ALL ON public.customer_settings TO service_role;
ALTER TABLE public.customer_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_settings ON public.customer_settings FOR ALL TO authenticated USING(user_id = auth.uid()) WITH CHECK(user_id = auth.uid());
CREATE TABLE public.addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL, line1 text NOT NULL, line2 text NOT NULL DEFAULT '', city text NOT NULL, postal_code text NOT NULL, country text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.addresses TO authenticated; GRANT ALL ON public.addresses TO service_role;
ALTER TABLE public.addresses ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_addresses ON public.addresses FOR ALL TO authenticated USING(user_id = auth.uid()) WITH CHECK(user_id = auth.uid());
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, email text NOT NULL, total numeric NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'EUR', payment_status text NOT NULL DEFAULT 'pending', fulfillment_status text NOT NULL DEFAULT 'unfulfilled', items jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_orders ON public.orders FOR SELECT TO authenticated USING(user_id = auth.uid() OR public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.newsletter_subscribers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, consent_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.newsletter_subscribers TO authenticated; GRANT ALL ON public.newsletter_subscribers TO service_role;
ALTER TABLE public.newsletter_subscribers ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_subscribers ON public.newsletter_subscribers FOR SELECT TO authenticated USING(public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.support_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, subject text NOT NULL, message text NOT NULL, status text NOT NULL DEFAULT 'new', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.support_messages TO authenticated; GRANT ALL ON public.support_messages TO service_role;
ALTER TABLE public.support_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_messages ON public.support_messages FOR ALL TO authenticated USING(public.has_role(auth.uid(), 'admin')) WITH CHECK(public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.store_settings (key text PRIMARY KEY, value jsonb NOT NULL DEFAULT '{}');
GRANT SELECT, INSERT, UPDATE ON public.store_settings TO authenticated; GRANT ALL ON public.store_settings TO service_role;
ALTER TABLE public.store_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_store_settings ON public.store_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(), 'admin')) WITH CHECK(public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.catalog_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), printful_sync_id text UNIQUE, slug text NOT NULL UNIQUE, name text NOT NULL, description text NOT NULL DEFAULT '', price numeric NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'EUR', variants jsonb NOT NULL DEFAULT '[]', images jsonb NOT NULL DEFAULT '[]', published boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.catalog_products TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.catalog_products TO authenticated; GRANT ALL ON public.catalog_products TO service_role;
ALTER TABLE public.catalog_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_catalog ON public.catalog_products FOR SELECT TO anon, authenticated USING(published);
CREATE POLICY admin_catalog ON public.catalog_products FOR ALL TO authenticated USING(public.has_role(auth.uid(), 'admin')) WITH CHECK(public.has_role(auth.uid(), 'admin'));